
CREATE POLICY h_provider_proof ON time.notification_delivery FOR SELECT TO migration_owner USING(workspace_id=NULLIF(current_setting('app.workspace_id',true),'')::uuid AND EXISTS(SELECT 1 FROM core.workspace w WHERE w.id=workspace_id AND w.owner_user_id=NULLIF(current_setting('app.user_id',true),'')::uuid));
DO $$ DECLARE d text;BEGIN
 d:=pg_get_functiondef('ops.provider_history_known(text,jsonb)'::regprocedure);d:=replace(d,'''time.notification_attempt'',''time.notification_provider_event''','''time.notification_attempt'',''time.notification_provider_event'',''time.notification_delivery''');EXECUTE d;
 d:=pg_get_functiondef('ops.preserve_notification_effects()'::regprocedure);d:=replace(d,'JOIN time.notification_attempt a ON a.workspace_id=e.workspace_id AND a.id=e.attempt_id JOIN time.notification_delivery d ON d.workspace_id=a.workspace_id AND d.id=a.delivery_id','JOIN time.notification_delivery d ON d.workspace_id=e.workspace_id AND d.id=e.delivery_id');d:=replace(d,'SELECT jsonb_build_object(''time.notification_attempt''','SELECT jsonb_build_object(''time.notification_delivery'',COALESCE((SELECT jsonb_agg(to_jsonb(d)) FROM time.notification_delivery d WHERE d.workspace_id=scope AND d.reminder_occurrence_id=r.id),''[]''::jsonb),''time.notification_attempt''');EXECUTE d;
 d:=pg_get_functiondef('ops.apply_private_restore(uuid,bytea,uuid)'::regprocedure);d:=replace(d,'IN (''time.notification_attempt'',''time.notification_provider_event'')','IN (''time.notification_attempt'',''time.notification_provider_event'',''time.notification_delivery'')');d:=replace(d,'IF NOT ops.provider_history_known(entity->>''kind'',record) THEN','IF NOT(entity->>''kind''=''time.notification_delivery'' AND record->>''status'' IN (''scheduled'',''cancelled'')) AND NOT ops.provider_history_known(entity->>''kind'',record) THEN');EXECUTE d;
END $$;
